DROP TABLE IF EXISTS `actions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `actions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `area` enum('Governança','Técnico','Jurídico','Eco-Fin') COLLATE utf8mb4_unicode_ci NOT NULL,
  `itemCode` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `parentCode` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isGroup` int NOT NULL DEFAULT '0',
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `priority` enum('Alta','Média','Baixa') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('Pendente','Em Andamento','Concluído','Cancelado') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pendente',
  `requestDate` timestamp NULL DEFAULT NULL,
  `receiptDate` timestamp NULL DEFAULT NULL,
  `documentBase` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sortOrder` int NOT NULL DEFAULT '0',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `orgao` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `responsavelNome` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `responsavelCargo` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `responsavelTel` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `responsavelEmail` varchar(320) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dueDate` timestamp NULL DEFAULT NULL,
  `observacoes` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `project` enum('ribeira','sanea') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ribeira',
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=210001;
/*!40101 SET character_set_client = @saved_cs_client */;

