  `actionCode` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `orgao` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isRead` int NOT NULL DEFAULT '0',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=5160001;
